# Synteettinen Wilma v2 – testiympäristö. Kaikki henkilöt, yritykset ja tunnisteet
# ovat keksittyjä. Koottu julkaisuun ilman kommentteja.
from __future__ import annotations
from typing import Literal
Variant = Literal['v1', 'v2']
NAV_ITEMS = ('Viestit', 'Opetusryhmät', 'Työjärjestys', 'Oppimistehtävät / Tentit', 'Työpaikalla järjestettävä koulutus', 'Näytöt', 'Osaamisen tunnustaminen', 'Hakemukset ja päätökset', 'Tulosteet', 'Kyselyt', 'Tiedotteet')
SKIN_CSS = '\n:root{--w-nav:#12305a;--w-nav-line:rgba(255,255,255,.14);--w-bg:#ebebeb;--w-card:#fff;\n--w-border:#d6d6d6;--w-text:#333;--w-muted:#707070;--w-link:#1b62b3;--w-green:#5b8e21;\n--w-green-d:#4a7619;--w-tab:#7ba63c;--w-th:#3d74b6}\nhtml{background:var(--w-bg)}\nbody.ds-skin{margin:0;padding:64px 24px 56px;background:var(--w-bg);color:var(--w-text);\nfont:13px/1.5 "Open Sans","Segoe UI",Helvetica,Arial,sans-serif}\n.ds-skin a{color:var(--w-link)}\n.ds-skin a:hover{color:#0d4a8f}\n.ds-nav{position:absolute;top:0;left:0;right:0;height:46px;display:flex;align-items:stretch;\nbackground:var(--w-nav);color:#fff;white-space:nowrap;overflow:hidden;z-index:2000;\nfont-size:14px;box-shadow:0 1px 3px rgba(0,0,0,.25)}\n.ds-nav a{color:#fff;text-decoration:none}\n.ds-nav .ds-apps{display:flex;align-items:center;padding:0 14px;font-size:18px;letter-spacing:-2px;\nopacity:.9}\n.ds-nav .ds-brand{display:flex;align-items:center;padding:0 18px 0 4px;\nfont:italic 700 24px Georgia,"Times New Roman",serif;letter-spacing:-.5px}\n.ds-nav .ds-item{display:flex;align-items:center;padding:0 13px;\nborder-left:1px solid var(--w-nav-line)}\n.ds-nav .ds-item.ds-on,.ds-nav a.ds-item:hover{background:rgba(255,255,255,.12)}\n.ds-nav .ds-user{margin-left:auto;display:flex;flex-direction:column;justify-content:center;\npadding:0 16px;font-size:11px;line-height:1.25;border-left:1px solid var(--w-nav-line)}\n.ds-nav .ds-badge{display:inline-block;margin-top:2px;padding:1px 6px;border-radius:2px;\nbackground:#f0a43a;color:#1d1d1d;font-weight:700;font-size:9.5px;letter-spacing:.05em}\n.ds-nav .ds-more{display:none}\n.ds-nav .ds-more>summary{display:flex;align-items:center;height:100%;padding:0 16px;\ncursor:pointer;list-style:none;font-size:20px;border-left:1px solid var(--w-nav-line)}\n.ds-nav .ds-more>summary::-webkit-details-marker{display:none}\n.ds-nav .ds-more[open]>summary{background:rgba(255,255,255,.12)}\n.ds-nav .ds-menu{position:fixed;top:46px;left:0;min-width:260px;max-width:100vw;\nmax-height:calc(100vh - 46px);overflow-y:auto;background:var(--w-nav);\nbox-shadow:0 4px 10px rgba(0,0,0,.3);white-space:normal}\n.ds-nav .ds-menu .ds-item{display:block;padding:11px 18px;border-left:0;\nborder-top:1px solid var(--w-nav-line)}\n@media (max-width:1560px){\n.ds-nav>.ds-item{display:none}\n.ds-nav .ds-more{display:block}\n}\n@media (max-width:700px){\n.ds-nav .ds-user{display:none}\n}\n.ds-skin [data-testid=synthetic-banner]{margin:0 0 6px;font-size:11px;color:var(--w-muted)}\n.ds-skin h1{font-weight:300;font-size:26px;line-height:1.25;margin:2px 0 14px;color:#333}\n.ds-skin h2{font-weight:300;font-size:21px;margin:18px 0 10px}\n.ds-skin h4{font-weight:600;font-size:13px;margin:12px 0 6px}\n.ds-skin label{font-weight:600;font-size:12px}\n.ds-skin .secondary-text{color:#333}\n.ds-skin .semi-bold{font-weight:600}\n.ds-skin input[type=text],.ds-skin input[type=search],.ds-skin input:not([type]),\n.ds-skin textarea,.ds-skin select,.ds-skin .form-control{font:inherit;color:#222;\nborder:1px solid #c6c6c6;border-radius:2px;padding:5px 8px;background:#fff;box-sizing:border-box;\nmax-width:100%}\n.ds-skin input[type=text]:focus,.ds-skin textarea:focus,.ds-skin .form-control:focus{\noutline:none;border-color:#6aa0d8;box-shadow:0 0 0 2px rgba(27,98,179,.15)}\n.ds-skin input[disabled],.ds-skin textarea[disabled]{background:#f4f4f4;color:#555}\n.ds-skin textarea{width:100%;min-height:58px;resize:vertical}\n.ds-skin button,.ds-skin input[type=submit],.ds-skin input[type=button]:not(.datepick-trigger),\n.ds-skin .btn{font:inherit;font-size:13px;line-height:1.3;color:#333;background:#fff;\nborder:1px solid #bcbcbc;border-radius:2px;padding:6px 18px;cursor:pointer}\n.ds-skin button[type=submit],.ds-skin input[name=savebtn],.ds-skin .btn-primary,\n.ds-skin #btn-save-choices{background:var(--w-green);border-color:var(--w-green-d);color:#fff}\n.ds-skin button[type=submit]:hover,.ds-skin input[name=savebtn]:hover,.ds-skin .btn-primary:hover{\nbackground:var(--w-green-d)}\n.ds-skin input.datepick-trigger{width:30px;height:28px;margin-left:-1px;border:1px solid #c6c6c6;\nbackground:#f5f5f5;cursor:pointer;vertical-align:top}\n.ds-skin a.openlist,.ds-skin .input-group-addon{display:inline-block;vertical-align:top;\nmin-width:34px;height:28px;box-sizing:border-box;margin-left:-1px;border:1px solid #c6c6c6;\nbackground:#f5f5f5;text-align:center;text-decoration:none;color:#3d74b6}\n.ds-skin a.openlist:empty::before{content:"\\2630";line-height:26px}\n.ds-skin table{border-collapse:collapse;width:100%;background:#fff;margin:6px 0 12px}\n.ds-skin th{background:#f4f4f4;color:var(--w-th);font-weight:400;text-align:left;padding:8px 10px;\nborder:1px solid #dedede}\n.ds-skin td{padding:6px 10px;border:1px solid #e4e4e4;vertical-align:top}\n.ds-skin tr:nth-child(even) td{background:#fafafa}\n.ds-skin .breadcrumb{display:flex;flex-wrap:wrap;list-style:none;padding:0;margin:0 0 12px;\nfont-size:12px}\n.ds-skin .breadcrumb li+li::before{content:"\\203A";padding:0 6px;color:#999}\n.ds-skin .list-group-item{display:block;padding:9px 12px;margin-bottom:-1px;background:#fff;\nborder:1px solid #dcdcdc;text-decoration:none}\n.ds-skin .list-group-item:hover{background:#f3f8fd}\n.ds-skin .list-group-item.icon-link::before{content:"+";display:inline-block;width:16px;\nfont-weight:700;color:var(--w-green)}\n.ds-skin .nav-tabs{display:flex;flex-wrap:wrap;list-style:none;padding:0 0 0 2px;margin:14px 0 0;\nborder-bottom:2px solid var(--w-tab)}\n.ds-skin .nav-tabs>li>a{display:block;margin:0 4px -2px 0;padding:8px 22px;background:#f7f7f7;\nborder:1px solid #c9c9c9;border-bottom:2px solid var(--w-tab);border-radius:7px 7px 0 0;\ncolor:#333;text-decoration:none}\n.ds-skin .nav-tabs>li.active>a{background:#fff;border:2px solid var(--w-tab);\nborder-bottom:2px solid #fff;font-weight:600}\n.ds-skin .nav-pills{display:flex;list-style:none;padding:0;margin:0 0 12px;gap:4px}\n.ds-skin .nav-pills>li>a{display:block;padding:6px 16px;border-radius:2px;text-decoration:none;\ncolor:#333;background:#fff;border:1px solid #d3d3d3}\n.ds-skin .nav-pills>li.active>a{background:var(--w-nav);border-color:var(--w-nav);color:#fff}\n.ds-skin .alert{padding:8px 12px;background:#fdf7e3;border:1px solid #efe0a8}\n.ds-skin .vismaicon-help{display:inline-block;width:15px;height:15px;border-radius:50%;\nbackground:#4a7fc1;color:#fff;font-size:10px;line-height:15px;text-align:center;vertical-align:middle}\n.ds-skin .vismaicon-help:empty::before{content:"?"}\n.ds-skin [role=listbox]{list-style:none;margin:2px 0 0;padding:4px 0;max-width:640px;\nbackground:#fff;\nborder:1px solid #cfcfcf;box-shadow:0 4px 10px rgba(0,0,0,.15)}\n.ds-skin [role=option]{padding:6px 14px;cursor:pointer}\n.ds-skin [role=option]:hover{background:#eaf2fb}\n.ds-footer{margin:28px auto 0;max-width:1180px;text-align:center;color:#8a8a8a;font-size:11px}\n/* Demoajon vaiheteksti (scripts/demo-ajo-v2.py): pseudoelementti, ei klikattava. */\nbody[data-ds-step]::after{content:attr(data-ds-step);position:fixed;left:18px;bottom:18px;\nmax-width:560px;padding:12px 16px;border-left:5px solid #f0a43a;border-radius:3px;\nbackground:#12305a;color:#fff;font-size:15px;line-height:1.45;white-space:pre-line;\nbox-shadow:0 3px 14px rgba(0,0,0,.35);z-index:3000;pointer-events:none}\n\n/* v1: sovelluksen ajama demo. Sivu on yksi valkoinen kortti. */\nbody.ds-v1{max-width:1060px;margin:0 auto;box-sizing:border-box}\n.ds-v1>h1{margin-top:6px}\n.ds-v1>form,.ds-v1>dl,.ds-v1>ul,.ds-v1>p:not([data-testid=synthetic-banner]),\n.ds-v1>nav+*{background:var(--w-card)}\n.ds-v1>form,.ds-v1>dl,.ds-v1>ul{border:1px solid var(--w-border);padding:16px 22px;margin:0 0 14px}\n.ds-v1>p:not([data-testid=synthetic-banner]){border:1px solid var(--w-border);padding:12px 22px;\nmargin:0 0 -1px}\n.ds-v1 form label{display:block;margin:12px 0 4px}\n.ds-v1 form input[type=text],.ds-v1 form input[type=search],.ds-v1 form input:not([type]){\nmin-width:320px}\n.ds-v1 ul{list-style:none}\n.ds-v1 ul li{padding:6px 0;border-bottom:1px solid #eee}\n.ds-v1 dl{display:grid;grid-template-columns:max-content 1fr;gap:4px 18px}\n.ds-v1 dt{font-weight:600;font-size:12px}\n.ds-v1 dd{margin:0}\n\n/* v2: oikean Wilman rakenne. Osiot ja lomakkeen lohkot valkoisina kortteina. */\n.ds-v2 #page-content-area{max-width:1240px;margin:0 auto}\n.ds-v2 main>div>div:has(>div>h1),.ds-v2 main>div:has(>h1),.ds-v2 main>div:has(>div>h1){\nbackground:var(--w-card);border:1px solid var(--w-border);padding:18px 26px;margin:0 0 14px}\n.ds-v2 main>div>div:has(>div>h1){display:inline-block;vertical-align:top;width:calc(50% - 8px);\nbox-sizing:border-box;margin-right:12px}\n.ds-v2 main>div:has(>div>div:has(>div>h1)){background:none;border:0;padding:0}\n.ds-v2 form.form-common>div{background:var(--w-card);border:1px solid var(--w-border);\npadding:18px 26px;margin:0 0 14px}\n.ds-v2 form.form-common>div:last-of-type{background:none;border:0;text-align:right}\n.ds-v2 .form-group,.ds-v2 main div:has(>label.secondary-text){margin:0 0 10px}\n.ds-v2 label.secondary-text{display:block;margin:10px 0 3px}\n.ds-v2 #tree-left-column{display:inline-block;vertical-align:top;width:44%;background:var(--w-card);\nborder:1px solid var(--w-border);padding:10px 16px;box-sizing:border-box}\n.ds-v2 #tree-right-column{display:inline-block;vertical-align:top;width:24%;margin-left:1.5%;\nbackground:var(--w-card);border:1px solid var(--w-border);padding:10px 16px;box-sizing:border-box}\n.ds-v2 #tree-right-column label{display:block;font-weight:400}\n.ds-v2 #choices-tree,.ds-v2 #choices-tree ul{list-style:none;padding-left:14px;margin:0}\n.ds-v2 #choices-tree a.a-val{display:block;padding:7px 10px;border-bottom:1px solid #eee;\ntext-decoration:none;color:#222}\n.ds-v2 #choices-tree a.a-val:hover{background:#eef5e3}\n.ds-v2 .sidepanel{position:fixed;top:46px;right:0;bottom:0;width:50%;overflow:auto;z-index:1500;\nbackground:#eeeeee;padding:16px 26px 30px;box-sizing:border-box;\nbox-shadow:-6px 0 14px rgba(0,0,0,.2)}\n.ds-v2 .sidepanel .sidepanel-title{font-size:26px;font-weight:300;margin:10px 0 2px}\n.ds-v2 .sidepanel .tab-content{background:#fff;border:1px solid var(--w-border);border-top:0;\npadding:14px 18px}\n.ds-v2 .sidepanel-close::before{content:"\\00BB";font-size:20px;text-decoration:none}\n.ds-v2 #actions-table th{color:var(--w-th)}\n.ds-v2 #actions-table label,.ds-skin label:has(>input[type=radio]),\n.ds-skin label:has(>input[type=checkbox]){font-weight:400}\n.ds-v2 table.node-tbl{margin:0;width:auto;background:none}\n.ds-v2 table.node-tbl td{border:0;padding:0;background:none}\n.ds-skin input.autocomplete{width:min(560px,75%)}\n.ds-v2>p:has(>a[href$="/specedu"]){display:none}\n.ds-v2 #forms-tab>div{margin-bottom:14px}\n.ds-v2 #forms-tab>div:nth-of-type(1)::before{content:"Työpaikalla järjestettävät koulutukset"}\n.ds-v2 #forms-tab>div:nth-of-type(3)::before{content:"Näytöt"}\n.ds-v2 #forms-tab>div:nth-of-type(4)::before{content:"Kurssin tiedot"}\n.ds-v2 #forms-tab>div::before{display:block;margin:4px 0 6px;font-weight:600;color:#333}\n.ds-v2 .ds-subtabs{max-width:1240px;margin:0 auto 12px}\n.ds-v2 .ds-crumbs{max-width:1240px;margin:0 auto 6px;font-size:12px}\n.ds-v2 .ds-crumbs span+span::before{content:"\\203A";padding:0 6px;color:#999}\n'
_V2_STUDENT_TABS_JS = '\n(function(){\n  var m = location.pathname.match(/^\\/profiles\\/students\\/(\\d+)(\\/[a-z]+)?/);\n  var crumbs = document.createElement(\'div\');\n  crumbs.className = \'ds-crumbs\';\n  crumbs.setAttribute(\'aria-hidden\', \'true\');\n  var parts = [\'<span><a href="/">Oma etusivu</a></span>\',\n               \'<span><a href="/profiles/students">Opiskelijat</a></span>\'];\n  if (m) {\n    var base = \'/profiles/students/\' + m[1];\n    parts.push(\'<span>Opiskelija</span>\');\n    var tabs = [[\'\', \'Perustiedot\'], [\'/choices\', \'Opinnot (HOPS)\'], [\'/specedu\', \'Suunnitelmat\']];\n    var ul = document.createElement(\'ul\');\n    ul.className = \'nav nav-tabs ds-subtabs\';\n    ul.setAttribute(\'aria-hidden\', \'true\');\n    ul.innerHTML = tabs.map(function(t){\n      var on = (m[2] || \'\') === t[0];\n      return \'<li\' + (on ? \' class="active"\' : \'\') + \'><a href="\' + base + t[0] + \'">\'\n        + t[1] + \'</a></li>\';\n    }).join(\'\');\n    var area = document.getElementById(\'page-content-area\');\n    if (area) area.parentNode.insertBefore(ul, area);\n  }\n  crumbs.innerHTML = parts.join(\'\');\n  var anchor = document.querySelector(\'.ds-subtabs\')\n    || document.getElementById(\'page-content-area\');\n  if (anchor && location.pathname !== \'/\') anchor.parentNode.insertBefore(crumbs, anchor);\n  // Ehdotuslista (#resultDiv) kenttään kiinni, kuten oikeassa Wilmassa.\n  // Sivun oma skripti luo listan vasta oman käsittelijänsä jälkeen, joten sijoitus viiveellä.\n  function placeNow(t) {\n    var box = document.getElementById(\'resultDiv\');\n    if (!box) return;\n    var r = t.getBoundingClientRect();\n    box.style.position = \'absolute\';\n    box.style.left = (r.left + window.scrollX) + \'px\';\n    box.style.top = (r.bottom + window.scrollY + 2) + \'px\';\n    box.style.width = r.width + \'px\';\n    box.style.zIndex = \'1800\';\n  }\n  function place(e) {\n    var t = e.target;\n    if (!t || !t.classList || !t.classList.contains(\'autocomplete\')) return;\n    setTimeout(function(){ placeNow(t); }, 0);\n    setTimeout(function(){ placeNow(t); }, 120);\n  }\n  document.addEventListener(\'focusin\', place, true);\n  document.addEventListener(\'input\', place, true);\n})();\n'

def _nav(variant: Variant) -> str:
    items = ''.join((f'<span class="ds-item">{t}</span>' for t in NAV_ITEMS))
    if variant == 'v2':
        brand = '<a class="ds-brand" href="/">Wilma</a>'
        students = '<a class="ds-item ds-on" href="/profiles/students">Opiskelijat</a>'
    else:
        brand = '<span class="ds-brand">Wilma</span>'
        students = '<span class="ds-item ds-on">Opiskelijat</span>'
    return f'<header class="ds-nav" aria-hidden="true"><span class="ds-apps">&#8942;&#8942;&#8942;</span>{brand}{items}{students}<details class="ds-more"><summary>&#9776;</summary><div class="ds-menu">{items}{students}</div></details><span class="ds-user">Demo Opettaja<br>Synteettinen oppilaitos<span class="ds-badge">SYNTEETTINEN TESTIYMPÄRISTÖ</span></span></header>'

def apply(html: str, variant: Variant) -> str:
    head_end = html.find('</head>')
    body_tag = '<body>'
    body_at = html.find(body_tag)
    if head_end < 0 or body_at < 0 or body_at < head_end:
        return html
    style = f'<style id="ds-skin">{SKIN_CSS}</style>'
    opening = f'<body class="ds-skin ds-{variant}">' + _nav(variant)
    footer = '<div class="ds-footer" aria-hidden="true">Synteettinen Wilma – testiympäristö. Kaikki henkilöt, yritykset ja arvot ovat keksittyjä.</div>'
    if variant == 'v2':
        footer += f'<script>{_V2_STUDENT_TABS_JS}</script>'
    out = html[:head_end] + style + html[head_end:body_at] + opening
    rest = html[body_at + len(body_tag):]
    close = rest.rfind('</body>')
    if close < 0:
        return out + rest
    return out + rest[:close] + footer + rest[close:]
